const VIEWS = ["cif", "eif"];
const VIEWPOINT_TOKENS = [
  { move: "U", suffix: "" }, { move: "U", suffix: "'" },
  { move: "R", suffix: "" }, { move: "R", suffix: "'" },
  { move: "F", suffix: "" }, { move: "F", suffix: "'" },
  { move: "V", suffix: "" }
];
const EIF_VIEWPOINT_MOVE_MAP = { U: "B", R: "R", F: "U", V: "V" };

